// Les sites à surveiller chaque lundi : ton site et ceux de tes clients. Adresse complète, sans « / » à la fin.
// « actif: false » pour en sauter un. Rien n'est publié : le flux lit seulement le plan du site, robots.txt et /avis.
const SITES = [
  { nom: 'Mon site (version de travail)', url: 'https://site-atelier-muel.gregoire-muel.workers.dev' },
  // { nom: 'Mon site', url: 'https://www.mon-domaine.fr' },
  // { nom: 'Boulangerie Exemple', url: 'https://www.boulangerie-exemple.fr' },
];
return SITES.filter((s) => s.actif !== false && /^https:\/\/[^\s/]+$/.test(s.url)).map((s) => ({ json: s }));

// Bilan de la semaine, site par site, sans IA : en ligne ? ouvert à Google ? dernière actualité ? lien d'avis ?
const sites = $('Sites suivis').all().map((i) => i.json);
const plans = $('Plan du site').all().map((i) => i.json), robots = $('Robots').all().map((i) => i.json), avis = $('Lien avis').all().map((i) => i.json);
const JOUR = 86400000, maintenant = Date.now();
const lignes = ['📊 Visibilité : bilan du lundi', ''];
sites.forEach((s, i) => {
  const plan = plans[i] || {}, rob = robots[i] || {}, av = avis[i] || {};
  const texteDe = (r) => String(r.data ?? r.body ?? ''); // réponse texte du nœud HTTP (champ « data »)
  const corps = texteDe(plan);
  lignes.push('• ' + s.nom);
  if (+plan.statusCode !== 200 || !corps.includes('<urlset')) { lignes.push('  ❌ Plan du site introuvable (' + (plan.statusCode || 'pas de réponse') + ') : le site est-il en ligne ?', ''); return; }
  const pages = (corps.match(/<loc>/g) || []).length;
  const bloque = /^Disallow:\s*\/\s*$/m.test(texteDe(rob));
  lignes.push(bloque ? '  ⚠️ Fermé à Google (site encore en version de travail : MAQUETTE = oui)' : '  ✅ En ligne, ' + pages + ' pages dans le plan du site');
  const dates = [...corps.matchAll(/<loc>[^<]*\/actualites\/[^<]+<\/loc><lastmod>(\d{4}-\d{2}-\d{2})<\/lastmod>/g)].map((m) => m[1]).sort();
  const derniere = dates[dates.length - 1];
  if (!derniere) lignes.push('  ✍️ Aucune actualité : publie la première (un chantier, une livraison, un conseil).');
  else {
    const jours = Math.floor((maintenant - Date.parse(derniere + 'T12:00:00Z')) / JOUR);
    lignes.push(jours > 14 ? `  ✍️ Dernière actualité il y a ${jours} jours : publie-en une cette semaine.` : `  ✅ Dernière actualité il y a ${jours} jour${jours > 1 ? 's' : ''} (${dates.length} au total)`);
  }
  lignes.push(+av.statusCode === 302 ? '  ✅ Lien /avis prêt (QR code)' : '  ⭐ Lien /avis pas réglé : page de modification, « Coordonnées, logo et mentions », « Lien pour laisser un avis Google ».');
  lignes.push('');
});
lignes.push('Cette semaine sur chaque fiche Google :', '1. un post (le fait de la semaine, avec une photo)', '2. deux ou trois photos récentes', '3. répondre à tous les nouveaux avis', '4. horaires et fermetures à jour');
if (new Date().getDate() <= 7) lignes.push('', 'Premier lundi du mois : regarde Search Console et Bing Webmaster Tools (pages indexées, erreurs), et demande 2 ou 3 avis à des clients contents.');
return [{ json: { texte: lignes.join('\n').slice(0, 4000) } }];
